INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Iran agrees to surrender enriched uranium stockpile by December 31, 2026?', 'This market will resolve to "Yes" if Iran publicly agrees to surrender its enriched uranium stockpile by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. An official pledge by Iran to surrender its enriched uranium stockpile will qualify for a “Yes” resolution whether as a unilateral announcement or part of an agreement with the U.S. or Israel. An agreement by Iran to surrender any amount of its enriched uranium stockpile will count. To qualify, Iran must publicly agr', 'politics', 'active', 89875.02, 967478.17, 90375.02, 967978.17);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('US x Iran Effective Ceasefire by July 31?', 'This market will resolve to “Yes” if there is a continuous 14-day period during which the United States does not take a qualifying military action against Iran that begins at any time between market creation and the specified end date, 11:59 PM ET. Otherwise this market will resolve to “No.” The first day of the 14-day period will be the calendar date (ET) after the most recent qualifying military action (or the date of market creation, if no qualifying action has occurred). The period runs thro', 'politics', 'active', 4353456.34, 43974.31, 4353956.34, 44474.31);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Scream 7 be the top grossing movie of 2026?', 'This market will resolve according to the title of the film with the highest 2026 gross according to the "Gross" column on https://www.boxofficemojo.com/year/2026/?grossesOption=calendarGrosses once data for December 31 is made available. Note: This market is about the movie''s domestic calendar gross in 2026 - dates outside of 2026 will not count toward this movie''s gross. In the event of an exact tie the film that comes first alphabetically will be considered the winner. If there is no final ', 'entertainment', 'active', 12251.01, 1212849.62, 12751.01, 1213349.62);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Philadelphia 76ers win the 2027 NBA Finals?', 'This market will resolve to "Yes" if the listed team is determined as the champion of the NBA for the 2026-27 season. Otherwise, it will resolve to "No". If at any point it becomes impossible for a listed team to be named as the champion of NBA for the 2026-27 season per the rules of NBA (e.g., participant is eliminated), the corresponding market will resolve to "No". If multiple teams are declared winners, this market will resolve in favor of the team whose listed name comes first alphabeticall', 'sports', 'active', 59966.51, 396052.55, 60466.51, 396552.55);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('US-Iran Final Nuclear Deal by August 31, 2026?', 'On June 14, 2026, the United States and Iran announced a written diplomatic agreement, including a 60-day extendable period in which both countries committed to negotiate toward a “final deal” regarding Iran’s nuclear program and other topics. This market resolves to “Yes” if a qualifying written diplomatic instrument between the United States and Iran has been mutually signed or adopted by the specified date, 11:59 PM ET. Otherwise, this market resolves to “No.” Unless the written instrument is', 'politics', 'active', 31238.16, 1921146.75, 31738.16, 1921646.75);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the U.S. invade Venezuela by December 31, 2026?', 'This market will resolve to "Yes" if the United States commences a military offensive intended to establish control over any portion of Venezuela between November 3, 2025 and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". For the purposes of this market, land de facto controlled by Venezuela or the United States as of September 6, 2025, 12:00 PM ET, will be considered the sovereign territory of that country. The resolution source for this market will be a consensus ', 'politics', 'active', 5327.02, 113051.28, 5827.02, 113551.28);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Nithya Raman win the 2026 Los Angeles mayoral election?', 'The 2026 Los Angeles mayoral election will be held on June 2, 2026, to elect the mayor of Los Angeles, California. If no candidate receives a majority of the vote, a runoff election will be held on November 3, 2026. This market will resolve according to the candidate that wins the election. The primary resolution source for this market will be a consensus of credible reporting; however, if there is any ambiguity in the results, this market will resolve according to official information from the ', 'politics', 'active', 253361.72, 409021.86, 253861.72, 409521.86);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('US announces end of Iranian blockade by August 15, 2026?', 'On July 13, 2026, Trump announced the United States would reinstate its naval blockade of Iran, targeting Iranian ships and customers. This market will resolve to “Yes” if the United States government, or an authorized representative of the United States government, publicly and officially announces the end, termination, lifting, or suspension of the United States’ naval blockade on Iranian ships and ships of Iranian customers, between market creation and the specified date, 11:59 PM ET. Otherwi', 'politics', 'active', 92916.76, 1145973.39, 93416.76, 1146473.39);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Xi Jinping out before 2027?', 'This market will resolve to "Yes" if China''s General Secretary of the Communist Party, Xi Jinping, is removed from power for any length of time between July 3, 2025, and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". CCP General Secretary Xi Jinping will be considered removed from power if he announces his resignation from his role as General Secretary, or is otherwise dismissed, detained, disqualified, or otherwise loses his position or is prevented from fulfillin', 'politics', 'active', 279907.63, 5739611.23, 280407.63, 5740111.23);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Reza Pahlavi lead Iran in 2026?', 'This market will resolve to “Yes” if Reza Pahlavi de facto holds and exercises the powers of the head of state of Iran by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No.” Reza Pahlavi will be considered to hold power if he exercises primary governing authority over the Iranian state during the specified timeframe, including effective control over the armed forces, national institutions, and core executive decision-making, regardless of formal title, constitutional des', 'politics', 'active', 195860.81, 5650730.52, 196360.81, 5651230.52);